// Bucket volunteers by days until their Safe Ministry cert expires.
// Input: raw Adminosaur /api/v1/people response.
// Output: one item with three arrays — expiring30, expiring60, expiring90.

const raw = $input.first().json;
const people = raw.data || raw.people || raw.results || [];

const today = new Date();
today.setHours(0, 0, 0, 0);

const MS_PER_DAY = 1000 * 60 * 60 * 24;

const expiring30 = [];
const expiring60 = [];
const expiring90 = [];

for (const person of people) {
  const expiryStr = person.safeMinistryCertExpiry
    || person.safe_ministry_cert_expiry
    || person.certExpiry
    || null;

  if (!expiryStr) continue;

  const expiry = new Date(expiryStr);
  if (isNaN(expiry.getTime())) continue;

  const daysUntil = Math.ceil((expiry - today) / MS_PER_DAY);

  // Skip already-expired or no-expiry-within-90-days
  if (daysUntil <= 0 || daysUntil > 90) continue;

  const entry = {
    name:       person.fullName || person.full_name || person.name || 'Unknown',
    email:      person.email || null,
    phone:      person.mobile || person.phone || null,
    expiryDate: expiryStr,
    daysUntil
  };

  if (daysUntil <= 30) {
    expiring30.push(entry);
  } else if (daysUntil <= 60) {
    expiring60.push(entry);
  } else {
    expiring90.push(entry);
  }
}

// Sort each bucket soonest-first
const byDays = (a, b) => a.daysUntil - b.daysUntil;
expiring30.sort(byDays);
expiring60.sort(byDays);
expiring90.sort(byDays);

const totalUpcoming = expiring30.length + expiring60.length + expiring90.length;

return [{
  json: {
    totalUpcoming,
    expiring30,
    expiring60,
    expiring90
  }
}];

// Build the HTML admin report email for all three expiry buckets.
const { expiring30, expiring60, expiring90, totalUpcoming } = $input.first().json;

const today = new Date().toLocaleDateString('en-AU', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

function tableRows(volunteers) {
  return volunteers.map(v =>
    `<tr>
      <td style="padding:6px 12px;">${v.name}</td>
      <td style="padding:6px 12px;">${v.expiryDate}</td>
      <td style="padding:6px 12px;font-weight:bold;">${v.daysUntil} days</td>
    </tr>`
  ).join('');
}

function section(title, colour, volunteers) {
  if (!volunteers.length) return '';
  return `
    <h3 style="color:${colour};margin-top:24px;">${title} (${volunteers.length})</h3>
    <table style="border-collapse:collapse;width:100%;font-family:sans-serif;font-size:14px;">
      <thead>
        <tr style="background:${colour};color:#fff;">
          <th style="padding:8px 12px;text-align:left;">Volunteer</th>
          <th style="padding:8px 12px;text-align:left;">Expiry Date</th>
          <th style="padding:8px 12px;text-align:left;">Days Remaining</th>
        </tr>
      </thead>
      <tbody>${tableRows(volunteers)}</tbody>
    </table>`;
}

const html = `
<!DOCTYPE html>
<html>
<body style="font-family:sans-serif;color:#222;max-width:640px;margin:0 auto;padding:20px;">
  <h2 style="color:#b22222;">⚠️ Safe Ministry Certification — Expiry Forecast</h2>
  <p>Report generated: <strong>${today}</strong></p>
  <p><strong>${totalUpcoming} volunteer(s)</strong> have Safe Ministry certifications expiring within the next 90 days.</p>
  ${section('🔴 Expiring within 30 days — ACTION REQUIRED', '#b22222', expiring30)}
  ${section('🟠 Expiring in 31–60 days — Follow up soon', '#cc6600', expiring60)}
  ${section('🟡 Expiring in 61–90 days — Monitor', '#997700', expiring90)}
  <hr style="margin-top:32px;"/>
  <p style="font-size:12px;color:#888;">Generated by Safe Ministry Connections (SMX). Do not reply to this email.</p>
</body>
</html>`;

return [{
  json: {
    subject: `SMX Expiry Forecast — ${totalUpcoming} cert(s) expiring within 90 days`,
    htmlBody: html,
    expiring30
  }
}];

// For the 30-day bucket, build individual SMS reminders for each volunteer
// who has a mobile number on record.
// Output: one item per volunteer to be sent an SMS.

const { expiring30 } = $input.first().json;

const withPhone = expiring30.filter(v => v.phone);

return withPhone.map(v => ({
  json: {
    phone: v.phone.replace(/\s+/g, ''),
    name: v.name,
    expiryDate: v.expiryDate,
    daysUntil: v.daysUntil,
    message: `Hi ${v.name.split(' ')[0]}, your Safe Ministry cert expires on ${v.expiryDate} (${v.daysUntil} days). Please renew ASAP to continue serving. Questions? Contact the Safe Ministry Co-ordinator.`
  }
}));
